import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import { loadFont as loadDM } from "@remotion/google-fonts/DMSans";
import { loadFont as loadLobster } from "@remotion/google-fonts/Lobster";
import { loadFont as loadMonoton } from "@remotion/google-fonts/Monoton";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadPacifico } from "@remotion/google-fonts/Pacifico";
import { loadFont as loadMarker } from "@remotion/google-fonts/PermanentMarker";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// MICAEL ANANIAS — designer gráfico e social media. Anúncio de 45 s: "a principal vitrine da sua empresa é a rede social".
// Identidade do site (micaelananias.com.br): quase preto #090A09, verde-limão #D5FF00, branco #F5F5F5; títulos em Outfit
// pesada e apertada com uma linha em itálico verde; rótulos em caixa alta espaçada com traço verde; botões em pílula
// com seta; cartões escuros de canto bem arredondado com o símbolo em marca-d'água. Tom mais sóbrio que os anúncios
// "agressivos": entradas suaves, pouco tremor, neon discreto (como no site), mas câmera em movimento em toda cena.
// O "depois" usa posts reais dele (ObrasPlan, do Behance) em public/micael/pNN.jpg.
// Locução "o locutor" sem pausas e a 1,1× (audio/micael-vo.wav), entra em 0,15 s. Sem áudio aqui.

const { fontFamily: OUT_F } = loadOutfit("normal", { weights: ["600", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: DM } = loadDM("normal", { weights: ["500", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: LOBSTER } = loadLobster("normal", { weights: ["400"], subsets: ["latin"] });
const { fontFamily: MONOTON } = loadMonoton("normal", { weights: ["400"], subsets: ["latin"] });
const { fontFamily: PACIFICO } = loadPacifico("normal", { weights: ["400"], subsets: ["latin"] });
const { fontFamily: MARKER } = loadMarker("normal", { weights: ["400"], subsets: ["latin"] });
const { fontFamily: ANTON } = loadAnton("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });

export const MA_FPS = 30;
const VO = 0.15;
export const MA_FRAMES = 45 * MA_FPS;
const BG = "#090A09";
const LIME = "#D5FF00";
const WHITE = "#F5F5F5";
const GRAY = "#9F9F9F";
const CARD = "#111211";
const EDGE = "#262826";
const WARN = "#FF5A4D";
const asset = (f: string) => staticFile(`micael/${f}`);
const post = (n: number) => asset(`p0${n}.jpg`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.out(Easing.back(1.4));
const k = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const v = (s: number) => s + VO;
const bump = (t: number, at: number, amt = 0.05, d = 0.4) => (t >= at ? amt * (1 - k(t, at, d)) : 0);
const glow = (c: string, s = 1) => `0 0 ${(5 * s).toFixed(1)}px ${c}, 0 0 ${(20 * s).toFixed(1)}px ${c}`;

// ───────── fundo: quase preto, clarão verde suave, o símbolo em marca-d'água e poeira ─────────
const Back: React.FC<{ t: number; warm?: number }> = ({ t, warm = 0 }) => (
  <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
    <div style={{ position: "absolute", left: 540 - 700 + Math.sin(t * 0.5) * 120, top: 760 - 700 + Math.cos(t * 0.4) * 160, width: 1400, height: 1400, borderRadius: 700, background: `radial-gradient(circle, rgba(213,255,0,${0.11 * (1 - warm)}) 0%, rgba(213,255,0,0) 62%)` }} />
    {warm > 0 ? <div style={{ position: "absolute", left: 540 - 700, top: 900 - 700, width: 1400, height: 1400, borderRadius: 700, background: `radial-gradient(circle, rgba(255,90,77,${0.08 * warm}) 0%, rgba(255,90,77,0) 62%)` }} /> : null}
    <Img src={asset("logo-mark.png")} style={{ position: "absolute", left: 540 - 520 + Math.sin(t * 0.3) * 60, top: 1100 + Math.cos(t * 0.35) * 50, width: 1040, opacity: 0.06, transform: `rotate(${(Math.sin(t * 0.5) * 6).toFixed(2)}deg) scale(${(1 + Math.sin(t * 0.7) * 0.06).toFixed(3)})` }} />
    <div style={{ position: "absolute", inset: -100, backgroundImage: "radial-gradient(rgba(245,245,245,0.09) 2px, transparent 2px)", backgroundSize: "54px 54px", backgroundPosition: `${(t * 12) % 54}px ${(t * 20) % 54}px` }} />
    {[0, 1, 2].map((i) => {
      const u = ((t * 0.38 + i * 0.37) % 1) * 2 - 0.5;
      return <div key={i} style={{ position: "absolute", left: -500 + u * 1600, top: 380 + i * 560, width: 620, height: 4, borderRadius: 2, background: "linear-gradient(90deg, rgba(213,255,0,0) 0%, rgba(213,255,0,0.55) 70%, rgba(245,245,245,0.7) 100%)", transform: "rotate(-18deg)" }} />;
    })}
    {Array.from({ length: 34 }, (_, i) => {
      const s = 6 + ((i * 37) % 4) * 4;
      const y = 2000 - ((t * (70 + ((i * 53) % 8) * 26) + i * 311) % 2100);
      const x = ((i * 197) % 1080) + Math.sin(t * 0.9 + i) * 40;
      return <div key={i} style={{ position: "absolute", left: x, top: y, width: s, height: s, borderRadius: s, background: i % 3 === 0 ? LIME : WHITE, opacity: 0.18 + ((i * 29) % 7) / 28 }} />;
    })}
    <AbsoluteFill style={{ background: "radial-gradient(95% 75% at 50% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.55) 100%)" }} />
  </AbsoluteFill>
);
// troca de cena: uma cortina verde arredondada sobe e leva a anterior
const Wipe: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  if (t < at - 0.34 || t > at + 0.38) return null;
  const p = interpolate(t, [at - 0.32, at + 0.34], [0, 1], { ...cl, easing: IN_OUT });
  return (
    <AbsoluteFill style={{ overflow: "hidden", zIndex: 30 }}>
      <div style={{ position: "absolute", left: -100, right: -100, top: 2100 - p * 4500, height: 2300, background: LIME, borderRadius: 160 }} />
      <div style={{ position: "absolute", left: -100, right: -100, top: 2260 - p * 4500, height: 2300, background: BG, borderRadius: 160 }} />
    </AbsoluteFill>
  );
};
const Stage: React.FC<{ children: React.ReactNode; origin?: string; depth?: number }> = ({ children, origin = "50% 50%", depth = 1500 }) => (
  <AbsoluteFill style={{ perspective: depth, perspectiveOrigin: origin }}>{children}</AbsoluteFill>
);

// ───────── texto: Outfit apertada, palavra por palavra; "it" = linha em itálico verde, como no site ─────────
type W = [string, number, string?];
const T0: React.FC<{ t: number; words: W[]; size: number; color?: string; it?: boolean; weight?: number }> = ({ t, words, size, color = WHITE, it, weight = 800 }) => (
  <div style={{ display: "flex", justifyContent: "center", alignItems: "baseline", gap: size * 0.22, whiteSpace: "nowrap", fontFamily: OUT_F, fontWeight: weight, fontSize: size, lineHeight: 1.06, letterSpacing: "-0.04em", color: it && color === WHITE ? LIME : color, transform: it ? "skewX(-9deg)" : undefined }}>
    {words.map(([w, at, c], i) => {
      const e = k(t, v(at) - 0.05, 0.42);
      return (
        <span key={i} style={{ display: "inline-block", opacity: k(t, v(at) - 0.05, 0.14), transform: `translateY(${((1 - e) * size * 0.5).toFixed(1)}px) scale(${(0.86 + 0.14 * pop(t, v(at) - 0.05, 0.45)).toFixed(3)})`, color: c, textShadow: (it && color === WHITE) || c === LIME ? glow("rgba(213,255,0,0.55)", 0.8) : undefined }}>{w}</span>
      );
    })}
  </div>
);
// os tamanhos pedidos nas cenas são multiplicados por 1,18 (texto maior no vídeo todo)
const T: React.FC<{ t: number; words: W[]; size: number; color?: string; it?: boolean; weight?: number }> = (p) => <T0 {...p} size={p.size * 1.18} />;
const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 0, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);
// rótulo do site: traço verde + caixa alta espaçada
const Label: React.FC<{ children: React.ReactNode; e: number; color?: string }> = ({ children, e, color = LIME }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 18, fontFamily: DM, fontWeight: 700, fontSize: 30, letterSpacing: "0.22em", color, opacity: e, whiteSpace: "nowrap" }}>
    <span style={{ width: 44 * e, height: 5, borderRadius: 3, background: color }} />
    {children}
  </div>
);

// ───────── posts amadores (cada um com uma cara) e o perfil arrumado do concorrente ─────────
const BAD: { bg: string; txt: string; font: string; fg: string; sx?: number; sy?: number; rot?: number; size?: number }[] = [
  { bg: "linear-gradient(160deg, #ff00cc 0%, #ffee00 100%)", txt: "PROMOÇÃO!!!", font: LOBSTER, fg: "#e60000", sx: 1.2, rot: -9 },
  { bg: "#00e05a", txt: "Bom dia", font: PACIFICO, fg: "#0022cc", rot: 4 },
  { bg: "repeating-conic-gradient(#8a8a8a 0% 25%, #b5b5b5 0% 50%) 0 0 / 34px 34px", txt: "confira", font: "Times New Roman, serif", fg: "#fff", size: 0.12 },
  { bg: "#ff3300", txt: "SEXTOU", font: MONOTON, fg: "#fff", size: 0.15 },
  { bg: "#ffffff", txt: "SUA LOGO", font: ANTON, fg: "#111", sx: 1.9, size: 0.12 },
  { bg: "linear-gradient(45deg, #00c3ff 0%, #ffff1c 100%)", txt: "Últimas vagas", font: MARKER, fg: "#7a00cc", rot: -5, size: 0.13 },
  { bg: "#1d1d1d", txt: "feliz natal", font: PACIFICO, fg: "#ff66c4", size: 0.14 },
  { bg: "#ffe600", txt: "LIGUE JÁ", font: ANTON, fg: "#e60000", sy: 1.5, size: 0.19 },
  { bg: "#8a2be2", txt: "10% off", font: LOBSTER, fg: "#39ff14", rot: 7 },
];
const BadTile: React.FC<{ i: number; s: number }> = ({ i, s }) => {
  const b = BAD[i % 9];
  return (
    <div style={{ width: s, height: s, background: b.bg, display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden", borderRadius: s * 0.04 }}>
      <div style={{ fontFamily: b.font, fontSize: s * (b.size ?? 0.17), color: b.fg, whiteSpace: "nowrap", transform: `rotate(${b.rot ?? 0}deg) scale(${b.sx ?? 1}, ${b.sy ?? 1})`, textShadow: i % 3 === 0 ? "3px 3px 0 #ffff00" : undefined }}>{b.txt}</div>
    </div>
  );
};
const GoodTile: React.FC<{ i: number; s: number }> = ({ i, s }) => {
  const dark = i % 2 === 0;
  return (
    <div style={{ width: s, height: s, background: dark ? "#1E3A5F" : "#EEF1F5", borderRadius: s * 0.04, position: "relative", overflow: "hidden" }}>
      <div style={{ position: "absolute", left: s * 0.12, top: s * 0.14, width: s * 0.5, height: s * 0.09, borderRadius: s, background: dark ? "#F2C14E" : "#1E3A5F" }} />
      <div style={{ position: "absolute", left: s * 0.12, top: s * 0.3, width: s * 0.66, height: s * 0.06, borderRadius: s, background: dark ? "#EEF1F5" : "#8C9BB0" }} />
      <div style={{ position: "absolute", right: s * 0.1, bottom: s * 0.1, width: s * 0.42, height: s * 0.42, borderRadius: i % 3 === 0 ? s : s * 0.08, background: dark ? "#2C5282" : "#F2C14E" }} />
    </div>
  );
};
const Grid: React.FC<{ kind: "bad" | "good" | "blank" | "posts"; s: number; gap?: number; t?: number }> = ({ kind, s, gap = 8, t = 0 }) => (
  <div style={{ display: "grid", gridTemplateColumns: `repeat(3, ${s}px)`, gap }}>
    {Array.from({ length: 9 }, (_, i) =>
      kind === "bad" ? <BadTile key={i} i={i} s={s} /> : kind === "good" ? <GoodTile key={i} i={i} s={s} /> : kind === "posts" ? <Img key={i} src={post([4, 5, 6, 7, 8, 9, 1, 2, 3][i])} style={{ width: s, height: s, objectFit: "cover", borderRadius: s * 0.04 }} /> : <div key={i} style={{ width: s, height: s, borderRadius: s * 0.04, background: `rgba(245,245,245,${(0.1 + 0.06 * Math.sin(t * 3 + i)).toFixed(3)})` }} />,
    )}
  </div>
);
const Avatar: React.FC<{ s: number; ring?: string; fill?: string; children?: React.ReactNode }> = ({ s, ring = EDGE, fill = "#2A2C2A", children }) => (
  <div style={{ width: s, height: s, borderRadius: s, border: `${Math.max(3, s * 0.05)}px solid ${ring}`, boxSizing: "border-box", background: fill, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, overflow: "hidden" }}>{children}</div>
);
// celular com um perfil de rede social
const Phone: React.FC<{ w: number; name: string; kind: "bad" | "good" | "blank" | "posts"; t: number; style?: React.CSSProperties; ring?: string; children?: React.ReactNode }> = ({ w, name, kind, t, style, ring, children }) => {
  const s = (w - 44 - 16) / 3;
  return (
    <div style={{ position: "absolute", width: w, borderRadius: w * 0.11, background: "#050505", border: `4px solid ${EDGE}`, padding: 18, boxSizing: "border-box", boxShadow: "0 50px 100px rgba(0,0,0,0.7)", ...style }}>
      <div style={{ borderRadius: w * 0.085, background: "#0E0F0E", overflow: "hidden", padding: "26px 0 22px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: w * 0.04, padding: `0 ${w * 0.05}px ${w * 0.04}px` }}>
          <Avatar s={w * 0.2} ring={ring ?? EDGE}>
            {kind === "posts" ? <Img src={asset("logo-mark.png")} style={{ width: "62%" }} /> : null}
          </Avatar>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: DM, fontWeight: 700, fontSize: w * 0.058, color: WHITE, whiteSpace: "nowrap" }}>{name}</div>
            <div style={{ display: "flex", gap: w * 0.03, marginTop: w * 0.025 }}>
              {[0, 1, 2].map((i) => (
                <div key={i} style={{ width: w * 0.12, height: w * 0.022, borderRadius: w, background: "#3A3C3A" }} />
              ))}
            </div>
          </div>
        </div>
        <div style={{ display: "flex", justifyContent: "center" }}>
          <Grid kind={kind} s={s} t={t} />
        </div>
      </div>
      {children}
    </div>
  );
};

// ───────── cena 1: não é a fachada, é a rede social ─────────
// abertura com as cores invertidas: fundo verde-limão e tudo em preto ("Hoje," gigante, a loja em silhueta). Em
// "não é a fachada" um círculo se abre a partir da loja e volta o esquema escuro do resto do vídeo.
const INKK = "#0B0C0B";
const FLIP = 2.88;
const Flip: React.FC<{ t: number }> = ({ t }) => {
  if (t > FLIP + 0.55) return null;
  const hole = interpolate(t, [FLIP, FLIP + 0.5], [0, 1500], { ...cl, easing: IN_OUT });
  const big = k(t, 0, 0.3);
  const up = io(t, 0.5, 0.36);
  const rise = pop(t, 0.56, 0.7);
  const mask = hole > 0 ? `radial-gradient(circle at 540px 1140px, transparent ${hole.toFixed(0)}px, #000 ${(hole + 4).toFixed(0)}px)` : undefined;
  return (
    <AbsoluteFill style={{ background: LIME, overflow: "hidden", WebkitMaskImage: mask, maskImage: mask }}>
      <div style={{ position: "absolute", left: 540 - 800 + Math.sin(t * 0.9) * 120, top: 900 - 800, width: 1600, height: 1600, borderRadius: 800, background: "radial-gradient(circle, rgba(255,255,255,0.5) 0%, rgba(255,255,255,0) 60%)" }} />
      <Img src={asset("logo-mark.png")} style={{ position: "absolute", left: 540 - 560 + Math.sin(t * 0.7) * 70, top: 1080 + Math.cos(t * 0.8) * 50, width: 1120, opacity: 0.1, filter: "brightness(0)", transform: `rotate(${(Math.sin(t * 0.9) * 6).toFixed(2)}deg)` }} />
      <div style={{ position: "absolute", inset: -100, backgroundImage: "radial-gradient(rgba(11,12,11,0.16) 2.5px, transparent 2.5px)", backgroundSize: "54px 54px", backgroundPosition: `${(t * 26) % 54}px ${(t * 40) % 54}px` }} />
      {[0, 1, 2].map((i) => {
        const u = ((t * 0.6 + i * 0.37) % 1) * 2 - 0.5;
        return <div key={i} style={{ position: "absolute", left: -500 + u * 1600, top: 420 + i * 520, width: 620, height: 6, borderRadius: 3, background: "linear-gradient(90deg, rgba(11,12,11,0) 0%, rgba(11,12,11,0.7) 100%)", transform: "rotate(-18deg)" }} />;
      })}
      <Stage depth={1400} origin="50% 58%">
        <div style={{ position: "absolute", inset: 0, transformStyle: "preserve-3d", transform: `translateZ(${(lin(t, 1.0, 5.3) * 200).toFixed(1)}px) rotateY(${mix(-14, 14, lin(t, 0.4, 5.3)).toFixed(2)}deg) rotateX(4deg)` }}>
          <div style={{ position: "absolute", left: 150, top: 760, width: 780, height: 760, transform: `translateY(${((1 - rise) * 1100).toFixed(1)}px)` }}>
            <div style={{ position: "absolute", left: 60, right: 60, top: 0, height: 110, borderRadius: 18, background: INKK, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: OUT_F, fontWeight: 800, fontSize: 56, color: LIME, letterSpacing: "0.02em" }}>SUA EMPRESA</div>
            <div style={{ position: "absolute", left: 0, right: 0, top: 130, height: 120, background: "repeating-linear-gradient(90deg, #0B0C0B 0 78px, #F5F5F5 78px 156px)", backgroundPosition: `${((t * 60) % 156).toFixed(1)}px 0`, clipPath: "polygon(6% 0, 94% 0, 100% 100%, 0 100%)" }} />
            <div style={{ position: "absolute", left: 30, right: 30, top: 250, bottom: 0, background: INKK }}>
              <div style={{ position: "absolute", left: 40, top: 60, width: 430, height: 340, borderRadius: 10, background: "#1E211D", border: "6px solid #2E322C", overflow: "hidden" }}>
                {[0, 1, 2].map((i) => (
                  <div key={i} style={{ position: "absolute", left: 40 + i * 130, bottom: 30, width: 96, height: 120 + (i % 2) * 70, borderRadius: 10, background: i === 1 ? LIME : "#F5F5F5", opacity: 0.92 }} />
                ))}
                <div style={{ position: "absolute", left: -60 + ((t * 260) % 700), top: -20, width: 70, height: 420, background: "rgba(255,255,255,0.14)", transform: "skewX(-20deg)" }} />
              </div>
              <div style={{ position: "absolute", right: 46, top: 60, width: 170, bottom: 0, borderRadius: "12px 12px 0 0", background: "#1E211D", border: "6px solid #2E322C", borderBottom: "none" }}>
                <div style={{ position: "absolute", left: 18, top: 190, width: 14, height: 60, borderRadius: 7, background: LIME }} />
              </div>
            </div>
            <div style={{ position: "absolute", left: -40, right: -40, bottom: -8, height: 8, borderRadius: 4, background: INKK }} />
            {[0, 1, 2].map((i) => {
              const u = (t * (0.3 + i * 0.07) + i * 0.4) % 1;
              return (
                <div key={i} style={{ position: "absolute", left: -260 + u * 1300, bottom: -6, width: 70, transform: `translateZ(${120 + i * 50}px) translateY(${(Math.abs(Math.sin(t * 9 + i)) * -10).toFixed(1)}px)` }}>
                  <div style={{ width: 46, height: 46, borderRadius: 23, background: i === 1 ? "#F5F5F5" : INKK, margin: "0 auto", border: `3px solid ${INKK}`, boxSizing: "border-box" }} />
                  <div style={{ width: 70, height: 150, borderRadius: "34px 34px 10px 10px", background: i === 1 ? "#F5F5F5" : INKK, marginTop: 6, border: `3px solid ${INKK}`, boxSizing: "border-box" }} />
                </div>
              );
            })}
          </div>
        </div>
      </Stage>
      <AbsoluteFill style={{ background: "linear-gradient(180deg, #D5FF00 0%, rgba(213,255,0,0.94) 30%, rgba(213,255,0,0) 40%)", opacity: k(t, 0.6, 0.4) }} />
      {t < 1.25 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: mix(720, 176, up), textAlign: "center", fontFamily: OUT_F, fontWeight: 800, fontSize: 330, letterSpacing: "-0.05em", lineHeight: 1, color: INKK, transform: `scale(${((1.5 - 0.5 * big) * mix(1, 0.1, up)).toFixed(3)}) rotate(${((1 - big) * -6).toFixed(2)}deg)`, opacity: 1 - lin(t, 0.8, 0.92) }}>Hoje,</div>
      ) : null}
      <Col top={210}>
        <Label e={k(t, 0.84, 0.3)} color={INKK}>HOJE</Label>
      </Col>
      <Col top={280} gap={2}>
        <T t={t} size={92} color={INKK} words={[["A", 0.79], ["principal", 0.89]]} />
        <T t={t} size={132} it color={INKK} words={[["vitrine", 1.55]]} />
        <T t={t} size={84} color={INKK} words={[["da", 1.97], ["sua", 2.11], ["empresa", 2.23]]} />
      </Col>
    </AbsoluteFill>
  );
};

const Vitrine: React.FC<{ t: number }> = ({ t }) => {
  const off = io(t, v(2.85) - 0.1, 0.6);
  const sw = k(t, v(3.97) - 0.2, 0.75);
  return (
    <>
      <Back t={t} />
      <Stage depth={1400} origin="50% 58%">
        <div style={{ position: "absolute", inset: 0, transformStyle: "preserve-3d", transform: `translateZ(${(lin(t, 1.0, 5.3) * 200).toFixed(1)}px) rotateY(${mix(-14, 14, lin(t, 0.4, 5.3)).toFixed(2)}deg) rotateX(4deg)` }}>
          {/* a fachada */}
          <div style={{ position: "absolute", left: 150, top: 760, width: 780, height: 760, opacity: mix(1, 0.3, off) * (1 - sw * 0.6), filter: `grayscale(${off}) brightness(${mix(1, 0.7, off)})`, transform: `translateZ(${(-sw * 500).toFixed(1)}px) scale(${(1 - sw * 0.1).toFixed(3)})` }}>
